// 提取并规范化传入的邮件数据
const item = $input.first();
const body = item.json.body || item.json;

// 提取发件人 (海外买家)
let from = body.from || body.sender || '';
if (typeof from === 'object' && from.address) {
  from = from.address;
} else if (typeof from === 'string' && from.includes('<')) {
  const match = from.match(/<([^>]+)>/);
  if (match) from = match[1];
}

// 提取收件人 (转发目标地址，如 rfq-default@quote.kelvinflow.com)
let to = body.to || body.recipient || '';
if (Array.isArray(to)) {
  to = to[0];
}
if (typeof to === 'object' && to.address) {
  to = to.address;
} else if (typeof to === 'string' && to.includes('<')) {
  const match = to.match(/<([^>]+)>/);
  if (match) to = match[1];
}

// 提取主题与正文
const subject = body.subject || 'RFQ Inquiry';
let text = body.text || body.plain || body.content || '';
if (!text && body.html) {
  text = body.html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

// 从目标邮箱地址中智能解析租户 ID (如 rfq-sales01@quote.kelvinflow.com -> sales01)
let tenantId = 'default';
if (to) {
  const match = to.match(/rfq-([^@]+)@/i);
  if (match && match[1]) {
    tenantId = match[1];
  }
}

return [{
  json: {
    from: from || 'buyer@example.com',
    to: to || 'rfq-default@quote.kelvinflow.com',
    subject,
    body: text,
    tenantId
  }
}];

// 记录成功运行日志与指标
const res = $input.first().json;
return [{
  json: {
    status: 'SUCCESS',
    quotationNumber: res.quotation?.quotationNumber,
    buyerName: res.quotation?.customerName,
    totalAmount: `${res.quotation?.currency} ${res.quotation?.totalAmountForeign}`,
    draftInjected: res.draftResult?.injected || false,
    reviewUrl: res.reviewUrl,
    timestamp: new Date().toISOString()
  }
}];

// 记录异常日志
const err = $input.first().json;
return [{
  json: {
    status: 'FAILED',
    error: err.error || 'Unknown error',
    timestamp: new Date().toISOString()
  }
}];
